.version 7.0
.target sm_80
.address_size 64

.visible .entry rmsnorm_kernel(
    .param .u64 x_ptr,
    .param .u64 out_ptr,
    .param .u32 batch,
    .param .u32 features,
    .param .u32 dim1,
    .param .u32 dim2,
    .param .f32 eps
)
{
    // registers
    .reg .pred %p;
    .reg .u32 %tid_x, %blockLinear, %b, %rem, %d1, %d2;
    .reg .u32 %tmp1, %tmp2, %feat_stride, %base, %feat_off;
    .reg .u64 %x, %out;
    .reg .u64 %addr_x, %addr_out;
    .reg .f16 %val_h;
    .reg .f32 %val_f, %sq_f, %sum_f, %mean_f, %rms_f, %norm_f, %eps_f;
    .reg .u32 %features_u, %feat_f;

