    ld.param.u64 %x, [x_ptr];
    ld.param.u64 %out, [out_ptr];
    ld.param.u32 %batch, [batch];
    ld.param.u32 %features_u, [features];
    ld.param.u32 %dim1, [dim1];
    ld.param.u32 %dim2, [dim2];
    ld.param.f32 %eps_f, [eps];

    // thread and block indices
    mov.u32 %tid_x, %tid.x;
    mov.u32 %blockLinear, %ctaid.x;

    // compute batch, d1, d2 from blockLinear
    mul.lo.u32 %tmp1, %dim1, %dim2;          // tmp1 = dim1*dim2
    div.u32 %b, %blockLinear, %tmp1;        // b = blockLinear / (dim1*dim2)
    mul.lo.u32 %tmp2, %b, %tmp1;
    sub.u32 %rem, %blockLinear, %tmp2;      // rem = blockLinear % (dim1*dim2)

    div.u32 %d1, %rem, %dim2;               // d1 = rem / dim2
    mul.lo.u32 %tmp2, %d1, %dim2;
    sub.u32 %d2, %rem, %tmp2;               // d2 = rem % dim2

    // compute base index = ((b*features)+0)*dim1*dim2 + d1*dim2 + d2
    mul.lo.u32 %tmp1, %b, %features_u;      // b*features
    mul.lo.u32 %tmp2, %tmp1, %dim1;         // b*features*dim1
    add.u32 %tmp2, %tmp2, %d1;              // +d1
    mul.lo.u32 %tmp2, %tmp2, %dim2;         // *dim2
    add.u32 %base, %tmp2, %d2;              // +d2

    // feature stride in elements (dim1*dim2)
    mul.lo.u32 %feat_stride, %dim1, %dim2;

    // compute element index for this thread
    mul.lo.u32 %feat_off, %tid_x, %feat_stride;
    add.u32 %tmp1, %base, %feat_off;        // total element index

    // convert to byte offset (half = 2 bytes)
    cvt.u64.u32 %addr_x, %tmp1;
    mul.lo.u64 %addr_x, %addr_x, 2;
    add.u64 %addr_x, %x, %addr_x;

