        ld.shared.f32 %tmp_f, [shmem + %tid_x*4];
        ld.shared.f32 %tmp2_f, [shmem + (%tid_x+16)*4];
        add.f32 %tmp_f, %tmp_f, %tmp2_f;
        st.shared.f32 [shmem + %tid_x*4], %tmp_f;
    }
    bar.sync 0;
    // step 8
    @(%tid_x < 8) {
        ld.shared.f32 %tmp_f, [shmem + %tid_x*4];
        ld.shared.f32 %tmp2_f, [shmem + (%tid_x+8)*4];
        add.f32 %tmp_f, %tmp_f, %tmp2_f;
        st.shared.f32 [shmem + %tid_x*4], %tmp_f;
    }
    bar.sync 0;
    // step 4
    @(%tid_x < 4) {
        ld.shared.f32 %tmp_f, [shmem + %tid_x*4];
        ld.shared.f32 %tmp2_f, [shmem + (%tid_x+4)*4];
        add.f32 %tmp_f, %tmp_f, %tmp2_f;
        st.shared.f32 [shmem + %tid_x*4], %tmp_f;
    }
    bar.sync 0;
    // step 2
    @(%tid_x < 2) {
        ld.shared.f32 %tmp_f, [shmem + %tid_x*4];
        ld.shared.f32 %tmp2_f, [shmem + (%tid_x+2)*4];
        add.f32 %tmp_f, %tmp_f, %tmp2_f;
        st.shared.f32 [shmem + %tid_x*4], %tmp_f;
    }
    bar.sync 0;
    // step 1 (final sum)
    @(%tid_x == 0) {
        ld.shared.f32 %tmp_f, [shmem];
        ld.shared.f32 %tmp2_f, [shmem + 4];
        add.f32 %sum_f, %tmp_f, %tmp2_f;           // sum of all 64 squares
        cvt.f32.u32 %feat_f, %features_u;
        div.f32 %mean_f, %sum_f, %feat_f;          // mean
        add.f32 %mean_f, %mean_f, %eps_f;          // + eps
        sqrt.approx.f32 %rms_f, %mean_f;           // rms
        st.shared.f32 [shmem], %rms_f;             // broadcast rms
    }
    bar.sync 0;

    // load rms value
    ld.shared.f32 %rms_f, [shmem];

    // normalize
    div.f32 %norm_f, %val_f, %rms_f;
    cvt.f16.f32 %val_h, %norm_f;

    // compute output address (same offset as input)
    add.u64 %addr_out, %out, %addr_x - %x;
    st.global.nc.f16 [%addr_out], %val_h;

    ret;
}
'''

class ModelNew(nn.Module):
    def __init__(self, num_features: int, eps: float = 1e-5):
